package com.harish.student_management.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="communication_messages") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class CommunicationMessage { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="conversation_id",nullable=false) CommunicationConversation conversation; @Column(nullable=false,columnDefinition="TEXT") String content; @Column(length=20) String messageType; @Column(name="sender_role",nullable=false,length=20) String senderRole; @Column(name="is_read",nullable=false) Boolean read; @Column(name="created_at",updatable=false) LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();if(read==null)read=false;if(messageType==null)messageType="TEXT";}}
